#!/usr/bin/env python3
"""Generate the AgentAPI skill's index from the Qiniu Developer Center sidebar."""

from __future__ import annotations

import argparse
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
import re
import time
from urllib.error import HTTPError, URLError
from urllib.parse import quote, urljoin, urlsplit
from urllib.request import Request, urlopen


from bs4 import BeautifulSoup, Tag


SOURCE = "https://developer.qiniu.com/agentapi"
USER_AGENT = "Qiniu-AgentAPI-Skill-Docs/1.0"
INDEX = Path("skills/agentapi/references/INDEX.md")
LINK = re.compile(r"\]\((https?://[^)\s]+)\)")
RETRYABLE_STATUS = {429, 500, 502, 503, 504}


def check_url(url: str) -> str | None:
    request = Request(url, headers={"User-Agent": USER_AGENT})
    for attempt in range(1, 4):
        try:
            with urlopen(request, timeout=15) as response:
                if response.geturl() != url:
                    return f"redirects to {response.geturl()}"
                if response.status != 200:
                    return f"HTTP {response.status}"
                return None
        except HTTPError as error:
            message = f"HTTP {error.code}"
            error.close()
            if error.code not in RETRYABLE_STATUS:
                return message
        except (URLError, TimeoutError) as error:
            message = str(error)
        if attempt < 3:
            time.sleep(attempt)
    return message


def render_node(node: Tag, depth: int = 0) -> list[str]:
    anchor = node.find("a", class_="node-title", recursive=False)
    if anchor is None or not anchor.get("href"):
        raise ValueError("documentation sidebar item is missing its title or link")

    title = " ".join(anchor.get_text(" ", strip=True).split())
    if not title:
        raise ValueError("documentation sidebar item has an empty title")
    if "计费" in title:
        return []
    label = re.sub(r"([\\*_{}\[\]`])", r"\\\1", title)

    href = anchor["href"]
    url = None
    if href != "#" and not href.startswith("javascript:"):
        url = urljoin(SOURCE, href)
        parts = urlsplit(url)
        if parts.scheme != "https" or parts.netloc != urlsplit(SOURCE).netloc:
            raise ValueError(f"unexpected documentation link: {url}")
        if "billing" in parts.path.rsplit("/", 1)[-1].lower().split("-"):
            return []
        url = quote(url, safe=":/?&=#%+@!$,;~")

    children = []
    for child in node.select(":scope > ol > li, :scope > ul > li"):
        children.extend(render_node(child, depth + 1))
    if not url and not children:
        return []

    item = f"[{label}]({url})" if url else f"**{label}**"
    if depth == 0:
        heading = f"## {item if url else label}"
        return [heading, "", *children] if children else [heading]
    return [f"{'  ' * (depth - 1)}- {item}", *children]


def render_index(html: bytes) -> str:
    soup = BeautifulSoup(html, "html.parser")
    groups = soup.select(".topic-sidebar-wrap .doctree > ul > li")
    entries = []
    for group in groups:
        section = render_node(group)
        if section:
            entries.extend(["", *section])
    if not any(LINK.search(line) for line in entries):
        raise ValueError("no documentation links found in the official sidebar")

    header = [
        "# AgentAPI 文档索引",
        "",
        "<!-- Generated by .github/scripts/sync-agentapi-doc-index.py -->",
        "",
        f"下列链接按七牛开发者中心的目录排列。[查看官网目录]({SOURCE})",
    ]
    return "\n".join(header + entries).rstrip() + "\n"


def check_links(index: Path, content: str) -> bool:
    urls = {}
    for number, line in enumerate(content.splitlines(), start=1):
        for url in LINK.findall(line):
            urls.setdefault(url, number)

    failed = 0
    with ThreadPoolExecutor(max_workers=4) as executor:
        for url, error in zip(urls, executor.map(check_url, urls)):
            if error is not None:
                print(f"{index}:{urls[url]}: {url}: {error}")
                failed += 1
    print(f"Checked {len(urls)} AgentAPI documentation links. Failed: {failed}.")
    return failed == 0


def main(index: Path = INDEX, *, check: bool = False) -> int:
    request = Request(SOURCE, headers={"User-Agent": USER_AGENT})
    with urlopen(request, timeout=15) as response:
        if response.geturl() != SOURCE:
            raise ValueError(f"documentation index redirects to {response.geturl()}")
        updated = render_index(response.read())
    if not check_links(index, updated):
        return 1
    if index.exists() and index.read_bytes() == updated.encode("utf-8"):
        print(f"{index} is up to date.")
        return 0
    if check:
        print(f"{index} differs from the official documentation sidebar.")
        return 1

    index.write_text(updated, encoding="utf-8")
    print(f"Updated {index}.")
    return 0


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check without writing the index.")
    args = parser.parse_args()
    try:
        raise SystemExit(main(check=args.check))
    except (OSError, ValueError) as error:
        parser.exit(1, f"{error}\n")
